const parentMain=r=>r.startsWith('/presupuesto')?'/presupuesto':r.startsWith('/patrimonio')?'/patrimonio':r.startsWith('/movimientos')||r.startsWith('/pendientes')?'/movimientos':['/real','/indicadores','/diagnostico','/analisis','/mas'].some(p=>r.startsWith(p))?'/analisis':r==='/inicio'||r==='/estado'?'/inicio':'/gestion';
