 if(name==='pending')db.records.push(...[{concept:'Compra general',cents:-1200,path:'Alimentación',discretion:'Necesario'},{concept:'Ajuste de compra',cents:200,path:'Alimentación / Supermercado'},{concept:'Abono pendiente',cents:700,path:''},{concept:'Cargo pendiente',cents:-300,path:''},{concept:'Devolución de ahorro',cents:500,path:'Ahorro / Cuenta de ahorro'},{concept:'Rectificación de nómina',cents:-400,path:'Ingresos / Salario'}].map((r,i)=>({id:`pending-${i}`,date:'2026-01-10',type:'REAL',account:'Cuenta principal',discretion:'',...r})));
 if(name==='incomeMissing')db.records=db.records.filter(r=>!(r.type==='PRESUPUESTO'&&r.path.startsWith('Ingresos')&&r.date==='2026-03-01'));
 if(['incomeZero','incomeNegative'].includes(name))db.records.forEach(r=>{if(r.type==='PRESUPUESTO'&&r.path.startsWith('Ingresos'))r.cents=name==='incomeZero'?0:-10000;});
