function euro(c,signed=true){return `${c<0?'−':c>0&&signed?'+':''}${new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2,useGrouping:'always'}).format(Math.abs(c)/100)} €`;}
const sum=rows=>rows.reduce((s,r)=>s+r.cents,0);
const period=()=>`${months[month].toLowerCase()} de ${year}`;
const key=()=>`${year}-${String(month+1).padStart(2,'0')}`;
const inBranch=(p,branch,direct=false)=>!branch|| (direct?p===branch:p===branch||p.startsWith(branch+' / '));
function rows(type,cat='',annual=false,direct=false){return db.records.filter(r=>r.type===type&&r.date.startsWith(annual?String(year):key())&&inBranch(r.path,cat,direct));}
function budget(cat='',annual=false){return sum(rows('PRESUPUESTO',cat,annual));}
function real(cat='',annual=false){return sum(rows('REAL',cat,annual));}
function roots(){return db.cats.filter(c=>!c.path.includes(' / '));}
const accountActive=a=>(!a.start||a.start<=key())&&(!a.end||a.end>=key());
const accountLiquidity=(a,k=key())=>a.periods?.filter(p=>p.from<=k).sort((a,b)=>a.from.localeCompare(b.from)).at(-1)?.liquidity||a.liquidity;
function liquidityEditor(id){const a=db.accounts.find(a=>a.id===id);if(!a)return title('Ficha no disponible','Vuelve a las fichas');const periods=a.periods||[{from:a.start,liquidity:a.liquidity}];return title('Periodos de liquidez · '+esc(a.name),'Los cambios tienen fecha explícita; no reinterpretan automáticamente fotos anteriores')+`<form id="liquidityForm" data-record="${a.id}" class="card"><div id="formError" class="formerror" role="alert"></div><h2>Periodos actuales</h2>${periods.map((p,i)=>`<div class="minirow"><span>Desde ${p.from}${periods[i+1]?' hasta '+periods[i+1].from+' (exclusivo)':' en adelante'}</span><strong>${p.liquidity}</strong></div>`).join('')}<div class="formgrid section">${inputField('Aplicar desde · mes de referencia','from',key(),'month')}<label>Liquidez del periodo<select name="liquidity">${['Líquida','Media','No líquida'].map(v=>`<option ${accountLiquidity(a)===v?'selected':''}>${v}</option>`).join('')}</select></label></div><p class="guidance section">Una fecha dentro de un periodo lo divide conservando los meses anteriores. Una fecha igual a su inicio corrige explícitamente ese periodo. Los intervalos se mantienen contiguos dentro de vigencia.</p><div class="formfooter"><button class="primary">Revisar cambio de periodo</button><button type="button" data-action="back">Cancelar</button></div></form>`;}
function saveLiquidity(form){const a=db.accounts.find(a=>a.id===form.dataset.record),data=new FormData(form),from=data.get('from'),liquidity=data.get('liquidity');if(!from||from<a.start||a.end&&from>a.end){formError('La fecha debe estar dentro de la vigencia. No se crea un hueco ni se cambia la vigencia desde este editor.');return;}modal('Confirmar clasificación histórica',`<p>${esc(a.name)} · ${liquidity} desde ${from}. Cambiará el subtotal líquido y el colchón de las fotos de ese periodo, sin cambiar sus valores ni el patrimonio neto.</p>`,[['Seguir editando',()=>{}],['Guardar periodo',()=>{if($('#fault').value){formError('No se guardó el periodo. Clasificación anterior conservada.');return;}const ps=a.periods||[{from:a.start,liquidity:a.liquidity}];const p=ps.find(p=>p.from===from);if(p)p.liquidity=liquidity;else ps.push({from,liquidity});a.periods=ps.sort((a,b)=>a.from.localeCompare(b.from));db.localChanged=true;db.revision++;dirty=false;back();notify('Periodo de liquidez guardado con fecha explícita.');},true]]);}
function photo(){const values=db.photos[key()];const pending=db.accounts.filter((a,i)=>accountActive(a)&&(!values||values[i]==null));if(pending.length)return {complete:false,pending,exists:!!values};const assets=values.reduce((s,v,i)=>s+(accountActive(db.accounts[i])&&db.accounts[i].type==='Activo'?v:0),0),debts=values.reduce((s,v,i)=>s+(accountActive(db.accounts[i])&&db.accounts[i].type==='Pasivo'?v:0),0),liquid=values.reduce((s,v,i)=>s+(accountActive(db.accounts[i])&&db.accounts[i].type==='Activo'&&accountLiquidity(db.accounts[i])==='Líquida'?v:0),0);return {complete:true,values,assets,debts,liquid,net:assets-debts};}
function indicator(){const p=photo();if(!p.complete)return {reason:p.exists?'foto_incompleta':'foto_ausente',text:p.exists?'Foto patrimonial incompleta':'Falta foto patrimonial',action:'/patrimonio/foto'};const incomeCats=roots().filter(c=>c.income).map(c=>c.path);const incomeRows=rows('PRESUPUESTO','',true).filter(r=>incomeCats.some(c=>inBranch(r.path,c)));const missing=months.filter((_,m)=>!incomeRows.some(r=>Number(r.date.slice(5,7))===m+1));if(missing.length)return {reason:'ingresos_incompletos',text:'Presupuesto anual de ingresos incompleto',missing,action:'/presupuesto/mensual'};const income=sum(incomeRows);if(income<=0)return {reason:income===0?'ingresos_nulos':'ingresos_negativos',text:income===0?'Ingresos presupuestados nulos':'Ingresos presupuestados no positivos',action:'/presupuesto/mensual'};return {value:p.liquid/(income/12),income,liquid:p.liquid};}
