function stat(label,cents,sub='',className='',path='',signed=true){const value=cents==null?'Sin dato':euro(cents,signed).replace(' €','');return `<article class="card stat ${className}"><span class="label">${label}</span><div class="value"><span>${value}</span>${cents==null?'':'<span class="unit">€</span>'}</div><div class="sub">${sub}</div>${path?link('Ver detalle',path):''}</article>`;}
