function categoryTable(cats,type){const annual=type!=='state';const cardRows=cats.map(c=>{const rv=real(c.path,annual),bv=budget(c.path,annual),has=rows('PRESUPUESTO',c.path,annual).length;return `<article class="card"><h3>${esc(c.name)}</h3><p class="muted">${esc(c.path)} · Rama completa</p>${type!=='budget'?`<div class="minirow"><span>Real</span><button class="link num" data-source="real" data-cat="${esc(c.path)}" data-annual="${annual}">${euro(rv)}</button></div>`:''}${type!=='real'?`<div class="minirow"><span>Presupuesto</span><button class="link num" data-source="budget" data-cat="${esc(c.path)}" data-annual="${annual}">${has?euro(bv):'Sin presupuesto'}</button></div>`:''}${type==='state'?`<div class="minirow"><span>Diferencia<br><span class="muted">${has?(rv-bv>0?'↑ Favorable':rv-bv<0?'↓ Desfavorable':'Igual'):'Sin presupuesto'}</span></span><strong class="num">${euro(rv-bv)}</strong></div>`:''}</article>`;}).join('');
 const headers=annual?months.map(m=>`<th class="money">${m}</th>`).join('')+'<th class="money">Total año</th>':'<th class="money">Presupuesto</th><th class="money">Real</th><th class="money">Diferencia</th>';
 const cell=(c,source,m,a=false)=>{const records=db.records.filter(r=>r.type===(source==='budget'?'PRESUPUESTO':'REAL')&&r.date.startsWith(a?String(year):`${year}-${String(m+1).padStart(2,'0')}`)&&inBranch(r.path,c));return `<td class="money"><button class="cell" data-focus="${source}-${esc(c)}-${m}" data-source="${source}" data-cat="${esc(c)}" data-month="${m}" data-annual="${a}">${source==='budget'&&!records.length?'Sin presupuesto':euro(sum(records))}</button></td>`;};
 const tr=c=>`<tr><td class="indent${c.path.split(' / ').length-1}"><strong>${esc(c.name)}</strong><br>${treeButton(c)}${type!=='budget'?`<br><button class="link" data-source="real" data-cat="${esc(c.path)}" data-scope="direct" data-annual="${annual}">Ver real directo</button>`:''}<span class="muted">${c.path.split(' / ').length===1?'Rama completa':esc(c.path)}</span></td>${annual?months.map((_,m)=>cell(c.path,type,m)).join('')+cell(c.path,type,month,true):cell(c.path,'budget',month)+cell(c.path,'real',month)+`<td class="money">${euro(real(c.path)-budget(c.path))}</td>`}</tr>`;
 const sc=type==='real'?`<tr><td>Sin clasificar</td>${months.map((_,m)=>`<td class="money"><button class="cell" data-source="real" data-cat="~" data-month="${m}">${euro(sum(db.records.filter(r=>r.type==='REAL'&&!r.path&&r.date.startsWith(`${year}-${String(m+1).padStart(2,'0')}`))))}</button></td>`).join('')}<td class="money"><button class="cell" data-source="real" data-cat="~" data-annual="true">${euro(sum(rows('REAL','',true).filter(r=>!r.path)))}</button></td></tr>`:'';
 const total=annual?months.map((_,m)=>cell('',type,m)).join('')+cell('',type,month,true):cell('','budget',month)+cell('','real',month)+`<td class="money">${euro(real()-budget())}</td>`;
 return `<p class="muted">${annual?'Año completo · enero a diciembre. Desplaza horizontalmente la matriz.':'Las filas padre incluyen sus descendientes; el total suma cada registro una sola vez.'}</p>${annual?'<div class="mobilerows"><button data-action="matrix">Mostrar / ocultar matriz completa</button></div>':''}<div class="${annual?'matrix-slot':'desktoprows'}"><div class="tablewrap" role="region" tabindex="0" aria-label="${type==='budget'?'Presupuesto anual':type==='real'?'Real anual':'Estado mensual'} · tabla completa"><table class="${annual?'matrix':''}"><caption>${annual?year:period()} · importes firmados en EUR · pulsa una cifra para abrir su origen</caption><thead><tr><th>Categoría</th>${headers}</tr></thead><tbody>${cats.map(tr).join('')}${sc}<tr class="total"><td>Total firmado · sin duplicar padres</td>${total}</tr></tbody></table></div></div><div class="${annual?'section':'mobilerows'}"><div class="${annual?'mobilerows':''} flowlist">${annual?`<p class="muted">Resumen de todas las categorías · total anual. La matriz de doce meses está disponible arriba.</p>`:''}${annual?annualCards(cats,type):cardRows}${type==='real'?`<article class="card"><h3>Sin clasificar</h3><button class="link num" data-source="real" data-cat="~" data-annual="true">${euro(sum(rows('REAL','',true).filter(r=>!r.path)))}</button></article>`:''}</div></div>`;
}
function budgetHome(){return title('Presupuesto',`Año ${year} · mes enfocado: ${months[month].toLowerCase()}`,btn('Captura mensual','/presupuesto/mensual',true)+btn('Preparar año siguiente','/presupuesto/propuesta'),'Planificación')+`<div class="grid3">${stat('Resultado presupuestado del año',budget('',true),'Suma de doce meses','budget-stat','/presupuesto/detalle')}${stat('Ingresos presupuestados',sum(rows('PRESUPUESTO','',true).filter(r=>roots().some(c=>c.income&&inBranch(r.path,c.path)))),'Categorías con raíz marcada Ingreso')}${stat('Mes enfocado',budget(),period(),'','/presupuesto/mensual')}</div><section class="section"><div class="sectionline"><h2>Partidas del año</h2>${link('Ver detalle','/presupuesto/detalle')}</div><div class="grid2">${roots().map(c=>`<article class="card"><div class="sectionline"><h3>${esc(c.name)}</h3><span class="tag">${c.income?'Ingreso':'Salida'}</span></div><div class="stat"><div class="value"><span>${rows('PRESUPUESTO',c.path,true).length?euro(budget(c.path,true)):'Sin presupuesto'}</span></div></div><p class="muted">${rows('PRESUPUESTO',c.path,true).length} partidas · ${year}</p><button class="link" data-source="budget" data-cat="${esc(c.path)}" data-annual="true">Abrir partidas ↗</button></article>`).join('')}</div></section>`;}
function annualReal(){return title('Real anual',`Año ${year} completo · fecha de valor · incluye Sin clasificar`,btn('Ver detalle','/real/detalle'),'Análisis')+`<div class="grid3">${stat('Resultado real anual',real('',true),'Suma firmada · doce meses','primary-stat','/real/detalle')}${stat('Enero',sum(db.records.filter(r=>r.type==='REAL'&&r.date.startsWith(`${year}-01`))),'Mes del año seleccionado')}${stat('Febrero',sum(db.records.filter(r=>r.type==='REAL'&&r.date.startsWith(`${year}-02`))),'Mes del año seleccionado')}</div><section class="card section"><h2>Resultado por mes</h2><div class="legend"><span>Real · EUR firmado</span></div>${annualChart()}<div class="minirows">${months.map((m,i)=>`<div class="minirow"><span>${m}</span><button class="link num" data-source="real" data-cat="" data-month="${i}">${euro(sum(db.records.filter(r=>r.type==='REAL'&&r.date.startsWith(`${year}-${String(i+1).padStart(2,'0')}`))))}</button></div>`).join('')}</div></section><section class="section"><h2>Por categoría · total del año</h2><div class="grid2">${roots().map(c=>`<article class="card"><h3>${esc(c.name)}</h3><button class="link num" data-source="real" data-cat="${esc(c.path)}" data-annual="true">${euro(real(c.path,true))}</button><p class="muted">Rama completa · ${year}</p></article>`).join('')}<article class="card"><h3>Sin clasificar</h3><button class="link num" data-source="real" data-cat="~" data-annual="true">${euro(sum(rows('REAL','',true).filter(r=>!r.path)))}</button><p class="muted">Incluido en el total firmado</p></article></div></section>`;}
function annualChart(){const values=months.map((_,i)=>sum(db.records.filter(r=>r.type==='REAL'&&r.date.startsWith(`${year}-${String(i+1).padStart(2,'0')}`)))),min=Math.min(0,...values),max=Math.max(0,...values)||100, y=v=>150-(v-min)/(max-min)*110,z=y(0);return `<svg class="chart" role="img" aria-label="Real anual en EUR; cifras exactas en lista visible" viewBox="0 0 760 190"><line x1="90" x2="730" y1="${z}" y2="${z}" stroke="var(--control-border)"/><text x="4" y="35">${euro(max)}</text><text x="4" y="165">${euro(min)}</text>${values.map((v,i)=>`<rect x="${100+i*52}" y="${Math.min(y(v),z)}" height="${Math.max(1,Math.abs(y(v)-z))}" width="28" fill="var(--series-real)"/><text x="${114+i*52}" y="186" text-anchor="middle">${months[i].slice(0,3)}</text>`).join('')}</svg>`;}
function wealth(detail=false){const p=photo();return title(detail?'Detalle patrimonial':'Patrimonio',`Foto manual · 1 de ${period()} · no se deriva de movimientos`,btn(p.complete?'Corregir foto':'Registrar foto','/patrimonio/foto',true)+btn('Gestionar fichas','/patrimonio/fichas'),'Foto del día 1')+`<div class="grid3">${stat('Patrimonio neto',p.complete?p.net:null,p.complete?'Activos − deudas':'Faltan valores manuales','primary-stat',detail?'':'/patrimonio/detalle',false)}${stat('Activos',p.complete?p.assets:null,'Cuentas y cartera · foto manual','','',false)}${stat('Deudas',p.complete?p.debts:null,'Magnitud de pasivos · bloque independiente','','',false)}</div>${!p.complete?`<section class="section">${alert(`<h3>${p.exists?'Foto incompleta':'Falta la foto patrimonial'}</h3><p>Pendientes: ${p.pending.map(a=>esc(a.name)).join(', ')}. No se calculan subtotales parciales ni se arrastra otro mes.</p>`,'')} </section>`:''}<section class="section grid2"><div class="card"><h2>Activos · ${p.complete?euro(p.assets,false):'Sin dato'}</h2>${db.accounts.map((a,i)=>a.type==='Activo'&&accountActive(a)?`<div class="distributionrow"><div class="minirow"><span><strong>${esc(a.name)}</strong><br><span class="muted">${accountLiquidity(a)} · manual</span></span><strong class="num">${db.photos[key()]?.[i]!=null?euro(db.photos[key()][i],false):'Pendiente'}</strong></div>${p.complete&&p.assets>0?`<div class="distribution" style="width:${p.values[i]/p.assets*100}%" aria-hidden="true"></div>`:''}</div>`:'').join('')}${p.complete&&p.assets===0?'<p>Distribución no representable · activos cero</p>':''}<p class="muted">${p.complete?'Activos líquidos: '+euro(p.liquid,false):'Activos líquidos: Sin dato'}</p></div><div class="card"><h2>Deudas</h2>${db.accounts.map((a,i)=>a.type==='Pasivo'&&accountActive(a)?`<div class="minirow"><span>${esc(a.name)}</span><strong class="num">${db.photos[key()]?.[i]!=null?euro(db.photos[key()][i],false):'Pendiente'}</strong></div>`:'').join('')}<p class="muted">Se restan al calcular el patrimonio neto; no integran la distribución de activos.</p>${link('Ver detalle','/patrimonio/detalle')}</div></section>${detail?`<section class="section card"><h2>Fotos de ${year}</h2><p class="muted">Se consulta cada foto por separado. No hay suma anual de patrimonio.</p>${months.map((m,i)=>`<div class="minirow"><span>${m} · día 1</span><button class="link" data-photo-month="${i}">${db.photos[`${year}-${String(i+1).padStart(2,'0')}`]?.every(v=>v!=null)?'Foto registrada':'Sin dato'}</button></div>`).join('')}</section>`:''}`;}
function indicators(detail=false){const i=indicator();return title(detail?'Cómo se calcula el colchón':'Indicadores',`Foto del 1 de ${period()} · presupuesto de ${year}`,detail?'':btn('Ver detalle','/indicadores/detalle'),'Análisis')+`<section class="card"><span class="tag">Único indicador · definición v1</span><h2 class="section">Colchón de emergencia</h2><div class="stat"><div class="value"><span>${i.reason?'Sin dato':i.value.toLocaleString('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2})}</span>${i.reason?'':'<span class="unit">meses</span>'}</div></div>${i.reason?`<div class="section">${alert(`<strong>${i.text}</strong>${i.missing?`<p>Meses pendientes: ${i.missing.map(m=>`<button class="link" data-income-month="${months.indexOf(m)}">${m}</button>`).join(', ')}.</p>`:''}<p>Código: ${i.reason}</p>${btn(i.action.startsWith('/patrimonio')?'Completar foto':'Completar presupuesto',i.action,true)}`,'')}</div>`:`<p class="muted section">${euro(i.liquid,false)} de activos líquidos / (${euro(i.income)} / 12 = ${euro(i.income/12,false)} al mes)</p>`}<p>Activos líquidos de la foto completa / promedio mensual de ingresos anuales presupuestados.</p>${!detail?link('Ver detalle','/indicadores/detalle'):''}</section>${detail?`<section class="section card"><h2>Entradas y ausencias</h2><div class="minirow"><span>Foto del mes</span><span>${photo().complete?'Completa':'Sin dato'}</span></div><div class="minirow"><span>Ingresos anuales presupuestados</span><span>${i.income!=null?euro(i.income):'Revisar completitud de los doce meses'}</span></div><p class="section">Una foto completa con líquidos cero produce 0,00 meses. Falta de foto, foto incompleta, ingresos incompletos, nulos o negativos producen Sin dato, en ese orden.</p><div class="actions">${btn('Abrir foto','/patrimonio/foto')}${btn('Abrir presupuesto','/presupuesto/detalle')}</div><p class="guidance section">Sin objetivos, umbrales, puntuaciones ni recomendación financiera. La deuda y los activos de liquidez media no forman parte del numerador.</p></section>`:''}`;}
function options(cats=db.cats,chosen='',empty='Sin clasificar'){return `<option value="">${empty}</option>`+cats.map(c=>`<option value="${esc(c.path)}" ${c.path===chosen?'selected':''}>${esc(c.path)}${c.active?'':' · archivada'}</option>`).join('');}
function movementRows(pending=false){return db.records.filter(r=>r.type==='REAL'&&(pending?!r.path:filter.range==='year'?r.date.startsWith(String(year)):r.date.startsWith(key()))&&(!filter.batch||(filter.batch==='batch-reference'?!!r.ordinal&&!r.batch:r.batch===filter.batch))&&(!filter.category||(filter.category==='~'?!r.path:inBranch(r.path,filter.category,filter.scope==='direct')))&&(!filter.account||r.account===filter.account)&&(!filter.search||r.concept.toLowerCase().includes(filter.search.toLowerCase())));}
function movementList(pending=false,detail=false){const list=movementRows(pending),total=sum(list);return title(pending?'Categorizar pendientes':detail?'Detalle de movimientos':'Movimientos',`${filter.batch?'Lote '+esc(filter.batch)+' ? ':''}${pending?'Todos los periodos':filter.range==='year'?'Año '+year:period()} · ${list.length} registros`,pending?btn('Asignar selección','action:batch',true):btn('Registrar movimiento','/movimientos/nuevo',true)+btn('Importar CSV','/importaciones/csv'),'Actividad')+`${pending?alert('Los pendientes siguen incluidos en el total firmado. Selecciona uno o varios para asignar la misma categoría.',''):''}${stack.some(s=>s.sourceFilter)?`<div class="guidance section">Origen: ${esc([...stack].reverse().find(s=>s.sourceFilter).sourceValue)} al abrir · los cambios de datos o filtros pueden variar el subtotal. ${btn('Restablecer filtros del informe','action:originFilter')}</div>`:''}<section class="card"><div class="formgrid"><label>Buscar concepto<input id="search" value="${esc(filter.search)}" placeholder="Buscar en los registros visibles"></label><label>Cuenta<select id="accountFilter"><option value="">Todas las cuentas</option>${db.accounts.filter(a=>a.type==='Activo'&&a.name!=='Cartera').map(a=>`<option ${filter.account===a.name?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>${!pending?`<label>Categoría<select id="categoryFilter">${options(db.cats,filter.category,'Todas las categorías')}<option value="~" ${filter.category==='~'?'selected':''}>Sin clasificar</option></select></label><label>Alcance<select id="scope"><option value="branch" ${filter.scope==='branch'?'selected':''}>Rama completa</option><option value="direct" ${filter.scope==='direct'?'selected':''}>Solo directos</option></select></label>`:''}</div><div class="actions section">${btn('Aplicar filtros','action:filter',true)}${btn('Limpiar filtros','action:clearFilter')}${!pending?btn(filter.range==='year'?'Usar mes seleccionado':'Ver año completo','action:range'):''}</div></section><div class="sectionline section"><p class="muted">${filter.category?esc(filter.category)+' · ':''}${pending?'Todos los periodos':filter.range==='year'?`Rango propio: 01/01/${year}–31/12/${year}`:`Mes seleccionado: ${period()}`} · Total filtrado <strong class="num">${euro(total)}</strong></p>${pending?`<label class="check"><input id="selectAll" type="checkbox" ${list.length&&list.every(r=>selected.has(r.id))?'checked':''}>Seleccionar visibles</label>`:detail?'':link('Ver detalle','/movimientos/detalle')}</div>${list.length?`<div class="flowlist">${list.map(r=>`<article class="flowitem">${pending?`<label class="check"><input type="checkbox" data-select="${r.id}" ${selected.has(r.id)?'checked':''} aria-label="Seleccionar ${esc(r.concept)} ${euro(r.cents)}"></label>`:`<div class="iconbox">${icon('movimientos')}</div>`}<div class="itembody"><h3><button class="link" data-route="/movimientos/${r.id}">${esc(r.concept)}</button></h3><p>${r.date} · fecha de valor · ${esc(r.account)}</p><p>${esc(r.path)||'<span class="tag warn">Sin clasificar</span>'}</p></div><div class="itemamount"><strong class="num">${euro(r.cents)}</strong><span class="muted">${r.cents<0?'Salida':'Entrada'}</span></div>${pending?`<button data-categorize="${r.id}">Categorizar</button>`:''}</article>`).join('')}</div>`:`<div class="empty"><h2>${pending?'No hay pendientes con estos filtros':'No hay movimientos con estos filtros'}</h2><p>Amplía el periodo o limpia los filtros.</p>${btn('Limpiar filtros','action:clearFilter')}</div>`}${pending?`<p class="guidance section">${selected.size} seleccionados · la confirmación vuelve a validar toda la selección. Si cambió un registro, se rechaza el lote íntegro.</p>`:''}`;}
function openCategorization(ids){if(!ids.length){notify('Selecciona al menos un movimiento.','error');return;}modal('Asignar categoría',`<p>${ids.length} movimientos · todos los periodos. Conservan cuenta, fecha, signo y discrecionalidad.</p><label>Categoría<select id="batchCategory">${options(db.cats.filter(c=>c.active),'','Elige una categoría')}</select></label>`,[['Cancelar',()=>{}],['Confirmar asignación',()=>{const cat=$('#batchCategory').value;if(!cat){notify('Elige una categoría antes de confirmar.','error');return;}if($('#fault').value||ids.some(id=>!db.records.some(r=>r.id===id&&!r.path))){notify('No se ha asignado ningún movimiento. La selección cambió o falló la escritura. Revisa y vuelve a confirmar.','error');return;}db.records.filter(r=>ids.includes(r.id)).forEach(r=>r.path=cat);db.localChanged=true;db.revision++;selected.clear();render();notify(`${ids.length} movimientos categorizados. La foto patrimonial permanece manual.`);},true]]);}
function inputField(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function formError(text){$('#formError').innerHTML=esc(text);$('#formError').setAttribute('tabindex','-1');$('#formError').focus();}
function centsInput(value,zero=true){const t=String(value).trim();if(!/^[+-]?\d+([,.]\d{1,2})?$/.test(t))throw Error('Usa un importe con signo opcional y hasta dos decimales, sin miles ni símbolo €.');const c=Math.round(Number(t.replace(',','.'))*100);if(!Number.isSafeInteger(c)||(!zero&&c===0))throw Error('El movimiento debe tener un importe distinto de cero.');return c;}
function movementEditor(id){const r=db.records.find(r=>r.id===id),isNew=!r;return title(isNew?'Registrar movimiento':'Movimiento · '+esc(r.concept),`Cuenta, fecha de valor e importe firmado · ${period()}`)+`<form id="movementForm" class="card" data-record="${r?.id||''}"><div id="formError" class="formerror" role="alert"></div><div class="formgrid">${inputField('Concepto','concept',r?.concept||'')}${inputField('Fecha de valor','date',r?.date||key()+'-15','date')}<label>Cuenta<select name="account">${db.accounts.filter(a=>a.type==='Activo'&&a.name!=='Cartera').map(a=>`<option ${r?.account===a.name?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>${inputField('Importe firmado · EUR','amount',r?String(r.cents/100):'', 'text','inputmode="decimal" placeholder="-12,50"')}<label class="full">Categoría<select name="category">${options(db.cats.filter(c=>c.active||c.path===r?.path),r?.path)}</select></label>${inputField('Discrecionalidad · texto conservado','discretion',r?.discretion||'')}<p class="formhint">Una entrada positiva no convierte su categoría en Ingreso. No se crean contrapartidas ni se calculan saldos.</p></div>${r?.ordinal?`<p class="guidance section">Procedencia: historico-ejemplo.csv · registro ${r.ordinal} ${link('Ver lote','/importaciones/lotes/batch-reference')}</p>`:'<p class="muted section">Procedencia: registro manual sintético</p>'}<div class="formfooter"><button class="primary" type="submit">Guardar movimiento</button><button type="button" data-action="back">Cancelar</button>${isNew?'':`<button type="button" data-delete-movement="${r.id}">Eliminar movimiento</button>`}</div></form>`;}
function saveMovement(form){try{const data=new FormData(form),id=form.dataset.record,r=db.records.find(r=>r.id===id),date=data.get('date'),concept=data.get('concept').trim(),amount=centsInput(data.get('amount'),false);if(!concept||!/^\d{4}-\d{2}-\d{2}$/.test(date))throw Error('Completa concepto y fecha de valor.');if($('#fault').value)throw Error('No se guardó el movimiento. Conserva el borrador y reintenta.');const payload={date,concept,cents:amount,path:data.get('category'),account:data.get('account'),discretion:data.get('discretion'),type:'REAL'};if(r)Object.assign(r,payload);else db.records.push({id:'manual-'+uid++,...payload});db.localChanged=true;db.revision++;dirty=false;back();notify('Movimiento guardado en la muestra. '+(!date.startsWith(key())?`Está fuera de ${period()}; el periodo seleccionado no cambia.`:''));}catch(e){formError(e.message);}}
function monthlyBudget(){const list=rows('PRESUPUESTO');return title('Captura mensual',`${period()} · presupuestos separados de movimientos`,btn('Añadir partida','/presupuesto/partidas/nueva',true)+btn('Ver año','/presupuesto/detalle'),'Presupuesto')+`<div class="card stat"><span class="label">Resultado presupuestado</span><div class="value"><span>${euro(budget())}</span></div><p class="muted">${list.length} partidas · padre y descendiente no pueden coexistir en una rama del mes.</p></div><div class="flowlist section">${list.map(r=>`<article class="flowitem"><div class="itembody"><h3>${esc(r.path)}</h3><p>${r.date} · sin cuenta</p></div><strong class="num">${euro(r.cents)}</strong>${btn('Editar','/presupuesto/partidas/'+r.id)}</article>`).join('')||'<div class="empty"><h2>Sin presupuesto</h2><p>Añade una partida. Un cero registrado sí cuenta como presupuesto.</p></div>'}</div>`;}
function budgetEditor(id){const r=db.records.find(r=>r.id===id);return title(r?'Editar partida':'Añadir partida',`Presupuesto de ${period()} · importe interno firmado`)+`<form id="budgetForm" data-record="${r?.id||''}" class="card"><div id="formError" class="formerror" role="alert"></div><div class="formgrid"><label class="full">Categoría<select name="category">${options(db.cats.filter(c=>c.active||c.path===r?.path),r?.path,'Elige categoría')}</select></label>${inputField('Mes · día 1','date',r?.date||key()+'-01','date')}${inputField('Importe firmado · EUR','amount',r?String(r.cents/100):'','text','inputmode="decimal"')}<p class="guidance full">Se admite cero explícito. No se presupuestan simultáneamente padre y descendiente, ni se vincula una cuenta.</p></div><div class="formfooter"><button class="primary">Guardar partida</button><button type="button" data-action="back">Cancelar</button>${r?`<button type="button" data-delete-budget="${r.id}">Eliminar partida</button>`:''}</div></form>`;}
function saveBudget(form){try{const data=new FormData(form),id=form.dataset.record,r=db.records.find(r=>r.id===id),date=data.get('date'),cat=data.get('category'),c=centsInput(data.get('amount'));if(!cat||!/^\d{4}-\d{2}-01$/.test(date))throw Error('Elige categoría y primer día del mes.');if(db.records.some(p=>p.type==='PRESUPUESTO'&&p.id!==id&&p.date===date&&(inBranch(p.path,cat)||inBranch(cat,p.path))))throw Error('Conflicto: ya existe esta categoría, un padre o un descendiente en el mismo mes. No se guardó ningún cambio.');if($('#fault').value)throw Error('No se guardó la partida. Conserva el borrador para reintentar.');const dataRow={date,path:cat,cents:c,type:'PRESUPUESTO',concept:'Presupuesto',account:'',discretion:''};if(r)Object.assign(r,dataRow);else db.records.push({id:'budget-'+uid++,...dataRow});db.localChanged=true;db.revision++;dirty=false;back();notify('Partida guardada. Las cifras se recalculan desde la muestra.');}catch(e){formError(e.message);}}
function prepareProposal(){proposal=months.flatMap((m,i)=>roots().map(c=>{const base=sum(db.records.filter(r=>r.type==='REAL'&&r.date.startsWith(`${year}-${String(i+1).padStart(2,'0')}`)&&inBranch(r.path,c.path)));return {id:`proposal-${i}-${c.id}`,date:`${year+1}-${String(i+1).padStart(2,'0')}-01`,path:c.path,cents:Math.sign(base)*Math.ceil(Math.abs(base)/1000)*1000,base};}));proposalDraft=true;}
function proposalPage(){if(!proposalDraft)prepareProposal();const targetYear=Number(proposal[0]?.date.slice(0,4)||year+1),list=proposal.filter(r=>Number(r.date.slice(5,7))===month+1);return title('Propuesta para '+targetYear,`Origen: real de ${year} · revisión antes de sustituir`,btn('Confirmar propuesta','action:confirmProposal',true),'Presupuesto')+alert('Importes por raíz: real del mes equivalente y magnitud redondeada a la decena superior o igual. Meses sin reales: cero editable. El año de origen permanece intacto.','')+`<div class="progresssteps"><span class="step">1 · Real de origen</span><span class="step active">2 · Revisar y editar</span><span class="step">3 · Confirmar destino</span></div><section class="card"><h2>${months[month]} de ${targetYear}</h2><p class="muted">El selector superior elige el mes de revisión; el año destino está indicado en cada partida.</p><div class="flowlist">${list.map(r=>`<article class="flowitem"><div class="itembody"><h3>${esc(r.path)}</h3><p>Real de origen: ${euro(r.base)}</p></div><strong class="num">${euro(r.cents)}</strong><button data-edit-proposal="${r.id}">Editar / desglosar</button></article>`).join('')}</div><div class="minirow"><span>Total propuesto del año</span><strong class="num">${euro(sum(proposal))}</strong></div></section><section class="card section"><h2>Todos los meses del destino</h2>${months.map((m,i)=>`<div class="minirow"><span>${m} ${targetYear}</span><strong class="num">${euro(sum(proposal.filter(r=>Number(r.date.slice(5,7))===i+1)))}</strong></div>`).join('')}</section>`;}
function editProposal(id){const r=proposal.find(r=>r.id===id);modal('Editar propuesta · '+r.date,`<p>Origen ${esc(r.path)} · ${euro(r.base)}</p><label>Partida / desglose<select id="proposalCategory">${options(db.cats.filter(c=>c.active&&inBranch(c.path,r.path.split(' / ')[0])),r.path,'Elige categoría')}</select></label><label>Importe firmado · EUR<input id="proposalAmount" value="${r.cents/100}" inputmode="decimal"></label><p class="muted">Desglosar sustituye la partida padre; no la duplica.</p>`,[['Cancelar',()=>{}],['Guardar propuesta',()=>{try{const path=$('#proposalCategory').value,c=centsInput($('#proposalAmount').value);if(!path)throw Error('Elige categoría');if(proposal.some(p=>p.id!==id&&p.date===r.date&&(inBranch(p.path,path)||inBranch(path,p.path))))throw Error('Conflicto padre / descendiente');r.path=path;r.cents=c;dirty=true;render();notify('Borrador actualizado. Revisa y confirma el año destino.');}catch(e){notify(e.message,'error');}},true]]);}
function photoEditor(){const values=db.photos[key()]||[];return title('Registrar / corregir foto',`Referencia: 1 de ${period()} · valores manuales`)+`<form id="photoForm" class="card"><div id="formError" class="formerror" role="alert"></div><p>Deja una ficha vacía para conservarla pendiente. Un 0,00 explícito es un valor registrado.</p><div class="formgrid">${db.accounts.map((a,i)=>inputField(`${esc(a.name)} · ${a.type} · ${accountLiquidity(a)}`,`photo${i}`,values[i]!=null?String(values[i]/100):'','text','inputmode="decimal"')).join('')}</div><p class="guidance section">La foto no se calcula desde movimientos. Con fichas pendientes, Patrimonio e Indicadores muestran Sin dato.</p><div class="formfooter"><button class="primary">Guardar foto</button><button type="button" data-action="back">Cancelar</button></div></form>`;}
function savePhoto(form){try{const data=new FormData(form),values=db.accounts.map((a,i)=>{const v=data.get('photo'+i).trim();if(!v)return null;const c=centsInput(v);if(c<0)throw Error('Activos y pasivos requieren magnitudes no negativas.');return c;});if($('#fault').value)throw Error('No se guardó la foto. Conserva los valores para reintentar.');db.photos[key()]=values;db.localChanged=true;db.revision++;dirty=false;back();notify('Foto manual guardada para el día 1. '+(values.some(v=>v==null)?'Quedan fichas pendientes.':'Foto completa.'));}catch(e){formError(e.message);}}
function saveAccountCatalog(form){try{const data=new FormData(form),c=db.accounts.find(a=>a.id===form.dataset.record),name=data.get('name').trim(),start=data.get('start'),end=data.get('end'),type=data.get('type'),liquidity=data.get('liquidity');if(!name||!start)throw Error('Completa nombre e inicio de vigencia.');if(end&&end<start)throw Error('El último mes vigente no puede preceder al primero.');if(type==='Pasivo'&&liquidity!=='No aplica'||type==='Activo'&&liquidity==='No aplica')throw Error('Elige liquidez para activos; los pasivos usan No aplica.');if(c&&(type!==c.type||liquidity!==c.liquidity||start!==c.start))throw Error('Para una ficha existente, revisa la clasificación histórica en su editor de periodos. Esta muestra conserva tipo, liquidez e inicio; admite renombrar y fijar último mes.');if($('#fault').value)throw Error('No se guardó ningún cambio de ficha.');if(c){db.records.filter(r=>r.account===c.name).forEach(r=>r.account=name);c.name=name;c.end=end;}else{db.accounts.push({id:'account-'+uid++,name,type,liquidity,start,end});Object.values(db.photos).forEach(p=>p.push(null));}db.localChanged=true;db.revision++;dirty=false;back();notify('Ficha guardada en la muestra. Los meses fuera de vigencia no exigen su valor.');}catch(e){formError(e.message);}}
function catalogs(accounts=false){return title(accounts?'Fichas patrimoniales':'Categorías',accounts?'Vigencia, tipo y liquidez · valores siempre manuales':'Árbol de hasta tres niveles · la marca Ingreso pertenece a la raíz',btn(accounts?'Nueva ficha':'Nueva categoría',accounts?'/patrimonio/fichas/nueva':'/categorias/nueva',true),'Gestión')+`<div class="flowlist">${(accounts?db.accounts:db.cats).map(c=>`<article class="flowitem"><div class="iconbox">${icon(accounts?'patrimonio':'gestion')}</div><div class="itembody"><h3>${esc(c.name)}</h3><p>${accounts?`${c.type} · ${c.liquidity} · vigente desde enero 2026`:esc(c.path)+` · ${c.income?'Ingreso heredado':'Salida'}`}</p>${accounts?'':`<span class="tag ${c.active?'':'warn'}">${c.active?'Activa':'Archivada · histórico conservado'}</span>`}</div>${btn('Editar',accounts?'/patrimonio/fichas/'+c.id:'/categorias/'+c.id)}</article>`).join('')}</div>`;}
function catalogEditor(id,accounts=false){const c=(accounts?db.accounts:db.cats).find(c=>c.id===id);const parent=c?.path?.split(' / ').slice(0,-1).join(' / ')||'';return title(c?'Editar '+esc(c.name):accounts?'Nueva ficha':'Nueva categoría',accounts?'Las fichas no son saldos de movimientos':'Identidad estable · archivar conserva referencias y datos históricos')+`<form class="card" id="catalogForm" data-record="${c?.id||''}" data-accounts="${accounts}"><div id="formError" class="formerror" role="alert"></div><div class="formgrid">${inputField('Nombre','name',c?.name||'')}${accounts?`<label>Tipo<select name="type"><option ${c?.type==='Activo'?'selected':''}>Activo</option><option ${c?.type==='Pasivo'?'selected':''}>Pasivo</option></select></label><label>Liquidez<select name="liquidity">${['Líquida','Media','No líquida','No aplica'].map(v=>`<option ${c?.liquidity===v?'selected':''}>${v}</option>`).join('')}</select></label>${inputField('Inicio de vigencia','start',c?.start||key(),'month')}${inputField('Último mes vigente · opcional','end','','month')}<p class="guidance full">Este prototipo muestra el editor de vigencia y liquidez. Los periodos históricos y solapamientos mantienen su propietario EP-009; no cambies históricos desde un control general.</p>`:`<label>Padre<select name="parent">${options(db.cats.filter(p=>p.id!==c?.id&&p.active),parent,'Raíz · sin padre')}</select></label><label>Marca de raíz<select name="income"><option value="false" ${!c?.income?'selected':''}>Salida</option><option value="true" ${c?.income?'selected':''}>Ingreso</option></select></label><p class="guidance full">Los descendientes heredan el tipo del padre. Cambiar directamente la marca de una raíz usada se rechaza; un traslado conserva signos y referencias y valida conflictos de presupuesto.</p>`}</div>${accounts&&c&&c.type==='Activo'?link('Editar periodos de liquidez','/patrimonio/fichas/'+c.id+'/periodos'):''}<div class="formfooter"><button class="primary">Guardar ${accounts?'ficha':'categoría'}</button><button type="button" data-action="back">Cancelar</button>${!accounts&&c?`<button type="button" data-archive="${c.id}">${c.active?'Archivar rama':'Reactivar rama'}</button>`:''}</div></form>`;}
function saveCatalog(form){try{const data=new FormData(form),isAccounts=form.dataset.accounts==='true',list=isAccounts?db.accounts:db.cats,c=list.find(c=>c.id===form.dataset.record),name=data.get('name').trim();if(!name)throw Error('El nombre es obligatorio.');if(isAccounts){if(c)throw Error('Este recorrido conserva la edición histórica para EP-009. Revisa vigencias y liquidez en su suplemento específico antes de reutilizar aprobación.');throw Error('Alta de ficha representada; la persistencia de vigencias se implementa en el propietario EP-009.');}const parent=data.get('parent'),path=parent?parent+' / '+name:name,affected=c?db.cats.filter(p=>inBranch(p.path,c.path)):[],maxDepth=path.split(' / ').length+Math.max(0,...affected.map(p=>p.path.split(' / ').length-c.path.split(' / ').length));if(c&&inBranch(parent,c.path))throw Error('No se permite un ciclo o padre propio.');if(maxDepth>3)throw Error('El traslado o alta produciría un cuarto nivel.');const used=c&&db.records.some(r=>inBranch(r.path,c.path)),income=parent?db.cats.find(p=>p.path===parent).income:data.get('income')==='true';if(c&&!parent&&!c.path.includes(' / ')&&used&&income!==c.income)throw Error('La raíz tiene referencias en su rama; no se permite cambiar directamente su marca.');if(c&&!parent&&c.path.includes(' / ')&&used&&income!==c.income)throw Error('Promover a raíz conserva el tipo heredado de una rama usada.');const projected=db.records.filter(r=>r.type==='PRESUPUESTO').map(r=>({...r,path:c&&inBranch(r.path,c.path)?path+r.path.slice(c.path.length):r.path}));if(projected.some((r,i)=>projected.some((p,j)=>j!==i&&p.date===r.date&&(inBranch(p.path,r.path)||inBranch(r.path,p.path)))))throw Error('El traslado genera un conflicto padre / descendiente en un mes presupuestado. No cambió el árbol.');if($('#fault').value)throw Error('No se guardó ningún cambio de catálogo.');if(c){const old=c.path;db.cats.filter(p=>inBranch(p.path,old)).forEach(p=>{p.path=path+p.path.slice(old.length);p.income=income;});db.records.filter(r=>inBranch(r.path,old)).forEach(r=>r.path=path+r.path.slice(old.length));c.name=name;}else db.cats.push({id:'cat-'+uid++,name,path,income,active:true});db.localChanged=true;db.revision++;dirty=false;back();notify('Categoría guardada. Se conservan signos e identidades de registros.');}catch(e){formError(e.message);}}
function importPage(){return title('Importar movimientos y presupuesto','Seleccionar → revisar → confirmar → resultado', '', 'Importación')+`<div class="progresssteps"><span class="step active">1 · Seleccionar</span><span class="step">2 · Revisar</span><span class="step">3 · Resultado</span></div><section class="card"><h2>Elige una muestra sintética</h2><p>Este prototipo no lee extractos personales. El CSV histórico y el XLS de Openbank son recorridos distintos.</p><label>Archivo de prueba<select id="importSample"><option value="valid">historico-ejemplo.csv · 58 filas · ya importado</option><option value="new">actividad-nueva.csv · 2 reales sin categoría</option><option value="errors">errores.csv · fecha / importe / cuenta</option><option value="overlap">solapamiento.csv · posibles duplicados</option><option value="resolve">referencias-nuevas.csv · cuenta / raíz por resolver</option><option value="xls">Openbank.xls · 2 reales sintéticos · sin presupuesto</option></select></label><p class="guidance section">CSV: presupuesto con signo contrario, normalizado al importar. Dos filas Café idénticas del mismo archivo siguen siendo dos movimientos.</p><div class="actions section">${btn('Revisar archivo','action:reviewImport',true)}${btn('Ver historial','/importaciones')}</div></section>`;}
function importReview(){const repeat=importChoice==='valid'||db.imports.some(b=>b.id==='sample-'+importChoice),errors=importChoice==='errors',needs=importChoice==='resolve',overlap=importChoice==='overlap',xls=importChoice==='xls';return title('Revisión de importación',`${xls?'Openbank.xls':importChoice+'.csv'} · previsualizar no escribe datos`)+`<div class="progresssteps"><span class="step">1 · Seleccionar</span><span class="step active">2 · Revisar</span><span class="step">3 · Resultado</span></div>${repeat?alert('<strong>Ya importado · mismo contenido</strong><p>0 altas de cuentas, categorías, partidas y movimientos. Cambiar el nombre no evita la detección por huella.</p>','info'):errors?alert('<strong>El lote contiene errores. No se puede confirmar.</strong><p>Fila 2: fecha 2026-02-30 no existe. Fila 3: importe inválido. Fila 4: falta cuenta.</p>','error'):overlap?alert('Hay 2 posibles duplicados de otro archivo. Revisa sus registros; no se descartan por parecido.',''):''}<section class="card"><h2>Resumen completo del archivo</h2><div class="minirow"><span>Filas</span><strong>${repeat?58:errors?3:2}</strong></div><div class="minirow"><span>Altas reales</span><strong>${repeat||errors?0:2}</strong></div><div class="minirow"><span>Altas presupuestarias</span><strong>0</strong></div>${repeat?`<div class="minirow"><span>Presupuesto original · CSV</span><strong class="num">${euro(-1320000)}</strong></div><div class="minirow"><span>Presupuesto normalizado · interno</span><strong class="num">${euro(1320000)}</strong></div><div class="minirow"><span>Real del archivo</span><strong class="num">${euro(232965)}</strong></div>`:!errors?`<div class="minirow"><span>Total real firmado · antes y después</span><strong class="num">${euro(overlap?-2000:400)}</strong></div><div class="minirow"><span>Presupuesto CSV / interno</span><strong class="num">0,00 € / 0,00 €</strong></div>`:''}${needs?`<label class="section">Cuenta por resolver<select id="resolveAccount"><option value="">Selecciona vínculo</option><option>Cuenta principal</option><option>Cuenta de ahorro</option></select></label><label>Raíz nueva · Tipo explícito<select id="resolveIncome"><option value="">Elige marca</option><option value="false">Salida</option><option value="true">Ingreso</option></select></label><p class="muted">Crearás la raíz «Otros». La marca no se deduce del signo.</p>`:xls?`<label>Cuenta de destino<select id="resolveAccount"><option>Cuenta principal</option><option>Cuenta de ahorro</option></select></label>`:''}${!repeat&&!errors?`<div class="tablewrap section"><table><caption>Todos los registros sintéticos del archivo</caption><thead><tr><th>Fila / concepto</th><th>Fecha / tipo</th><th>Cuenta / categoría</th><th class="money">EUR original / interno</th></tr></thead><tbody><tr><td>2 · ${overlap?'Café':'Abono pendiente'}</td><td>${key()}-10 · REAL</td><td>${needs?'Por resolver':'Cuenta principal'}<br>${overlap?'Ocio':needs?'Otros · raíz nueva':'Sin clasificar'}</td><td class="money">${euro(overlap?-1000:700)}</td></tr><tr><td>3 · ${overlap?'Café':'Cargo pendiente'}</td><td>${key()}-10 · REAL</td><td>${needs?'Por resolver':'Cuenta principal'}<br>${overlap?'Ocio':needs?'Otros · raíz nueva':'Sin clasificar'}</td><td class="money">${euro(overlap?-1000:-300)}</td></tr></tbody></table></div>`:''}${overlap?'<label class="check section"><input id="acceptOverlap" type="checkbox">He revisado y quiero conservar las dos filas</label>':''}<div class="actions section">${!repeat&&!errors?btn('Confirmar importación','action:confirmImport',true):''}${btn(repeat?'Ver lote existente':'Cambiar archivo',repeat?'/importaciones/lotes/batch-reference':'/importaciones/csv')}${btn('Cancelar revisión','action:cancelReview')}</div><p class="muted section">La confirmación vuelve a validar referencias y conflictos. Un error rechaza el lote íntegro. No cambia fotos patrimoniales.</p></section>`;}
function confirmImport(){if(importChoice==='resolve'&&(!$('#resolveAccount').value||!$('#resolveIncome').value)){notify('Resuelve la cuenta y elige la marca explícita de la raíz.','error');return;}if(importChoice==='overlap'&&!$('#acceptOverlap').checked){notify('Revisa el solapamiento y confirma la decisión.','error');return;}if($('#fault').value){notify('No se importó ninguna fila. Falló la validación o escritura del lote; conserva la base anterior.','error');return;}const id='sample-'+importChoice;if(db.imports.some(b=>b.id===id)){notify('Ya importado · 0 altas.');return;}const account=$('#resolveAccount')?.value||'Cuenta principal',newCat=importChoice==='resolve';if(newCat&&!db.cats.some(c=>c.path==='Otros'))db.cats.push({id:'cat-'+uid++,name:'Otros',path:'Otros',income:$('#resolveIncome').value==='true',active:true});const overlap=importChoice==='overlap';db.records.push(...[0,1].map((n)=>({id:'import-'+uid++,type:'REAL',date:key()+'-10',concept:overlap?'Café':n?'Cargo pendiente':'Abono pendiente',cents:overlap?-1000:n?-300:700,path:overlap?'Ocio':newCat?'Otros':'',account,discretion:'',batch:id,ordinal:n+2})));lastImport={id,name:importChoice+'.csv',count:2,date:'12/10/2026'};db.imports.push(lastImport);db.localChanged=true;db.revision++;dirty=false;go('/importaciones/resultado');}
function importResult(){return title('Importación completada','Resultado confirmado en la muestra · sin cambios patrimoniales')+alert('2 movimientos importados · 0 partidas · lote íntegro.','info')+`<section class="card"><h2>Continúa con el lote</h2><div class="actions">${btn('Categorizar pendientes','/pendientes-categorizacion',true)}${btn('Ver lote','/importaciones/lotes/'+(lastImport?.id||'batch-reference'))}${btn('Repetir archivo','action:repeatImport')}${btn('Volver a movimientos','/movimientos')}</div></section>`;}
function importHistory(id){const b=db.imports.find(b=>b.id===id);return title(b?'Lote · '+esc(b.name):'Historial de importaciones','Identidad por contenido · procedencia conservada',btn('Importar CSV','/importaciones/csv'))+`<div class="flowlist">${(b?[b]:db.imports).map(b=>`<article class="card"><h3>${esc(b.name)}</h3><p class="muted">${b.date} · ${b.count} registros · huella conservada</p><div class="actions">${link('Ver procedencia','/importaciones/origen/'+b.id)}<button data-batch-records="${b.id}">Ver movimientos del lote</button>${btn('Categorizar pendientes','/pendientes-categorizacion')}</div></article>`).join('')}</div>`;}
function drive(){return title('Copia manual en Google Drive','Solo Subir copia o Descargar última copia inician una transferencia','', 'Copias y recuperación')+`<section class="card"><h2>Tu base local</h2><span class="tag ${db.localChanged?'warn':'good'}">${db.localChanged?'Cambios locales desde la copia conocida':'Sin cambios locales desde la copia conocida'}</span><div class="minirow"><span>Cuenta de muestra</span><strong>persona@example.invalid</strong></div><div class="minirow"><span>Versión de origen local</span><strong>${knownVersion}</strong></div><div class="minirow"><span>Última copia remota conocida</span><strong>${version} · 12/10/2026 09:00</strong></div><p class="muted">Metadatos de demostración. Abrir esta pantalla no consulta Drive. No hay conexión bancaria ni transferencias en segundo plano.</p><div class="actions section">${btn('Subir copia','action:upload',true)}${btn('Descargar última copia','action:download')}${btn('Copias locales','/copias-locales')}</div></section><section class="card section"><h2>Conserva el origen de cada copia</h2><p>Una versión remota distinta detiene la subida. Descargar valida la base completa y crea una copia previa antes de sustituirla. No se mezclan las dos versiones.</p></section>`;}
function upload(){modal('Subir copia local',`<p>Se validará la copia local y se consultará la versión remota antes de publicarla.</p><p>Origen local ${knownVersion}. Última remota conocida ${version}.</p>`,[['Cancelar',()=>{}],['Subir copia',()=>{if($('#fault').value==='conflict'){version='v2';render();notify('Hay una copia más reciente en Drive; no se ha subido tu copia local. Se conservan ambas bases. Puedes conservar local o Descargar última copia.','error');return;}if($('#fault').value){notify('No se confirmó la subida. Conserva la copia remota anterior y vuelve a consultar desde Subir copia.','error');return;}version='v'+(Number(version.slice(1))+1);knownVersion=version;db.localChanged=false;render();notify('Copia subida · 12/10/2026 · versión '+version+'. Simulación confirmada.');},true]]);}
function download(){modal('Descargar última copia',`<p>Versión consultada: ${$('#fault').value==='conflict'?'v2':version} · 12/10/2026 09:00.</p><p>${db.localChanged?'Hay cambios locales: dejarán de estar en la base activa al sustituirla.':'Se sustituirá la base activa por la copia remota validada.'}</p><p>Se descarga completa, se valida y se crea una copia local previa. Cancelar conserva la base.</p>`,[['Cancelar',()=>{}],['Descargar y sustituir',()=>{if(['write','invalid','backup'].includes($('#fault').value)){notify('No se descargó la copia; tus datos locales siguen disponibles. '+($('#fault').value==='backup'?'No se pudo crear el respaldo previo.':'La transferencia o validación falló.'),'error');return;}db.backups.push({id:'copy-'+uid++,date:'12/10/2026 · 10:00',version:knownVersion,label:'Antes de descargar',records:structuredClone(db.records),data:backupData()});installData(baseTemplate);knownVersion=version=$('#fault').value==='conflict'?'v2':version;db.localChanged=false;render();notify('Copia descargada y validada. La copia local previa está disponible para recuperar.');},true]]);}
function copies(id){const b=db.backups.find(b=>b.id===id);return title(baseActive?'Copias locales':'Recuperar base local',baseActive?'Copias previas recuperables · restauración manual':'No hay base utilizable. Los informes permanecen cerrados hasta validar una restauración.')+`${!baseActive?alert('No se ha abierto la base de datos. Elige una copia para recuperar.','error'):''}<div class="flowlist">${(b?[b]:db.backups).map(b=>`<article class="card"><h3>${b.label}</h3><p>${b.date} · ${b.version} · ${b.records.length} registros</p><p class="muted">Base SQLite sintética compatible · el servicio nativo verificará integridad.</p><div class="actions">${id?`<button class="primary" data-restore="${b.id}">Restaurar esta copia</button>`:btn('Ver copia','/copias-locales/'+b.id)}</div></article>`).join('')}</div>`;}
function restore(id){modal('Restaurar copia local','<p>Se validará y sustituirá la base activa. Cuando existe una base utilizable, se conserva un respaldo previo. No inicia ninguna descarga de Drive.</p>',[['Cancelar',()=>{}],['Restaurar y abrir',()=>{if($('#fault').value){notify('No se restauró la copia. Se conserva la base anterior, o la entrada de recuperación si no había base. Reintenta manualmente.','error');return;}if(baseActive)db.backups.push({id:'copy-'+uid++,date:'12/10/2026 · 10:00',version:knownVersion,label:'Antes de restaurar',records:structuredClone(db.records),data:backupData()});installData(db.backups.find(b=>b.id===id).data);db.localChanged=true;knownVersion=db.backups.find(b=>b.id===id).version;baseActive=true;dirty=false;stack=[];go('/inicio',false);notify('Base recuperada y abierta. Informes disponibles; sin transferencia remota.');},true]]);}
function analysis(more=false){return title(more?'Más':'Análisis','Consulta los flujos del año y las entradas de tu único indicador','',more?'Navegación':'Informes')+`<div class="grid2">${[['Real anual','El año completo por categorías y meses.','/real'],['Indicadores','Colchón de emergencia y datos que necesita.','/indicadores'],['Diagnóstico de coherencia','Comprobación manual de datos; solo lectura.','/diagnostico'],...(more?[['Gestión','Importaciones, catálogos, Drive y recuperación.','/gestion']]:[])].map(([name,desc,path])=>`<article class="card"><h2>${name}</h2><p class="muted">${desc}</p>${btn('Abrir '+name.toLowerCase(),path)}</article>`).join('')}</div>`;}
function management(){return title('Gestión','Herramientas para mantener tus datos locales','', 'Herramientas')+`<div class="grid2">${[['Importar CSV','Histórico de reales y presupuestos.','/importaciones/csv'],['Importar Openbank XLS','Revisión y cuenta de destino; muestra sintética.','/importaciones/openbank'],['Historial de importaciones','Lotes, origen y pendientes.','/importaciones'],['Categorías','Árbol y marca de ingreso de la raíz.','/categorias'],['Fichas patrimoniales','Cuentas, inversiones y pasivos manuales.','/patrimonio/fichas'],['Google Drive','Subir copia / Descargar última copia.','/drive'],['Copias locales','Ver y restaurar copias previas.','/copias-locales'],['Diagnóstico de coherencia','Ejecutar una revisión de solo lectura.','/diagnostico']].map(([name,desc,path])=>`<article class="card"><h2>${name}</h2><p class="muted">${desc}</p>${link('Abrir',path)}</article>`).join('')}</div>`;}
function diagnose(){return title('Diagnóstico de coherencia',`Revisión manual de ${period()} · datos de muestra`,btn(diagnostic?'Repetir diagnóstico':'Ejecutar diagnóstico','action:diagnose',true),'Análisis')+`<section class="card"><p>La revisión es de solo lectura. Abre el origen de un hallazgo para revisarlo; no se repara ni borra automáticamente.</p><p class="muted">Para revisar un solapamiento, elige Archivos solapados en la franja del prototipo. Las dos filas Café del mismo archivo no generan por sí solas un hallazgo.</p><label>Estado sintético a revisar<select id="diagnosticCase"><option value="pending">Pendientes válidos</option><option value="clean">Sin hallazgos</option><option value="duplicate">Posible duplicado</option><option value="skipped">Regla no ejecutada</option><option value="error">Error de lectura local</option><option value="stale">Resultado obsoleto</option></select></label></section>${diagnostic?`<section class="section">${diagnostic.case==='error'?alert('No se pudo leer la base local. No se presentan conteos como cero. Si la base es ilegible, abre Recuperación local.','error')+btn('Recuperación local','/copias-locales'):diagnostic.case==='stale'||diagnostic.revision!==db.revision?alert('Resultado obsoleto · hay cambios posteriores o un periodo distinto. Repite el diagnóstico para obtener una lectura nueva.',''):''}<div class="sectionline"><h2>Resultados de la revisión</h2><label>Severidad<select id="severity"><option value="">Todas</option><option>Pendiente</option><option>Aviso</option><option>Error</option><option>No ejecutada</option></select></label></div><div id="findings" class="flowlist">${diagnostic.items.length?diagnostic.items.map((r,i)=>`<article class="card finding" data-severity="${r.severity}"><span class="tag ${r.severity==='Pendiente'?'warn':''}">${r.severity}</span><h3 class="section">${r.title}</h3><p>${r.text}</p><button data-finding="${i}">Ver hallazgo y origen</button></article>`).join(''):`<div class="empty"><h2>${diagnostic.case==='error'?'No se completó la lectura':'Sin hallazgos'}</h2><p>${diagnostic.case==='error'?'Reintenta o abre recuperación.':'Las reglas ejecutadas no encontraron incidencias en esta muestra.'}</p></div>`}</div><p class="muted section">Resultado en memoria · sin historial ni exportación. Repetir es una acción explícita.</p></section>`:`<div class="empty section"><h2>Listo para revisar</h2><p>Pulsa Ejecutar diagnóstico. No se ejecuta al abrir la pantalla.</p></div>`}`;}
function runDiagnostic(){const type=$('#diagnosticCase').value;modal('Ejecutando diagnóstico','<p>Revisión de la muestra local · puedes cancelar antes de presentar resultados.</p>',[['Cancelar revisión',()=>notify('Diagnóstico cancelado. No se modificó ningún dato.')],['Ver resultado',()=>{diagnostic={case:type,period:key(),revision:db.revision,items:type==='pending'&&!photo().complete?[{severity:'Pendiente',title:'Foto pendiente',text:`Abrirá la foto del día 1 de ${period()}; una ausencia válida no es un error financiero.`,path:'/patrimonio/foto'}]:type==='duplicate'&&db.records.some(r=>r.batch==='different-file'||r.batch==='sample-overlap')?[{severity:'Aviso',title:'Posible duplicado',text:'Hay filas Café similares procedentes de archivos distintos. Revísalas; las dos filas idénticas del lote histórico se conservan como registros separados.',path:'/movimientos/detalle'}]:type==='skipped'?[{severity:'No ejecutada',title:'Comprobación no disponible',text:'La entrada de la regla no está disponible. No se afirma que haya pasado.',path:'/gestion'}]:[]};render();$('#diagnosticCase').value=type;},true]]);}
function budgetRecords(){const list=rows('PRESUPUESTO',filter.category,filter.range==='year',filter.scope==='direct');return title('Partidas de presupuesto',`${filter.range==='year'?'Año '+year:period()} · ${filter.category||'Todas las categorías'} · ${filter.scope==='direct'?'Solo directos':'Rama completa'}`,btn('Añadir partida','/presupuesto/partidas/nueva'))+`<section class="card"><div class="formgrid"><label>Categoría<select id="categoryFilter">${options(db.cats,filter.category,'Todas las categorías')}</select></label><label>Alcance<select id="scope"><option value="branch" ${filter.scope==='branch'?'selected':''}>Rama completa</option><option value="direct" ${filter.scope==='direct'?'selected':''}>Solo directos</option></select></label></div><div class="actions section">${btn('Aplicar filtros','action:filter')}${btn('Restablecer filtros del informe','action:originFilter')}</div><p class="muted section">${list.length} registros · subtotal filtrado <strong class="num">${euro(sum(list))}</strong>. El ámbito inicial de la cifra se conserva en Volver; filtrar cambia el ámbito visible.</p></section><div class="flowlist section">${list.map(r=>`<article class="flowitem"><div class="itembody"><h3>${esc(r.path)}</h3><p>${r.date} · partida · sin cuenta</p></div><strong class="num">${euro(r.cents)}</strong>${btn('Editar','/presupuesto/partidas/'+r.id)}</article>`).join('')||'<div class="empty"><h2>Sin presupuesto en este ámbito</h2><p>El cero implícito de una suma no crea una partida.</p></div>'}</div>`;}
const routeNames={'/inicio':'Inicio','/estado':'Estado del mes','/presupuesto':'Presupuesto','/presupuesto/mensual':'Captura mensual','/presupuesto/detalle':'Matriz de presupuesto','/presupuesto/propuesta':'Propuesta','/movimientos':'Movimientos','/movimientos/detalle':'Detalle de movimientos','/patrimonio':'Patrimonio','/patrimonio/detalle':'Detalle patrimonial','/patrimonio/foto':'Foto patrimonial','/analisis':'Análisis','/mas':'Más','/real':'Real anual','/real/detalle':'Matriz de real','/indicadores':'Indicadores','/indicadores/detalle':'Detalle del colchón','/gestion':'Gestión','/diagnostico':'Diagnóstico','/importaciones/csv':'Importar CSV','/importaciones/revision':'Revisión de importación','/importaciones':'Importaciones','/categorias':'Categorías','/patrimonio/fichas':'Fichas','/copias-locales':'Copias locales','/drive':'Google Drive'};
function routeContent(){
 if(route==='/inicio')return home();if(route==='/estado')return state();
 if(route==='/presupuesto')return budgetHome();if(route==='/presupuesto/mensual')return monthlyBudget();
 if(route==='/presupuesto/detalle')return title('Detalle del presupuesto',`Matriz completa de ${year}`,btn(expanded?'Contraer ramas':'Desplegar ramas','action:expand'))+categoryTable(visibleCats(),'budget');
 if(route==='/presupuesto/propuesta')return proposalPage();if(route==='/presupuesto/partidas')return budgetRecords();
 if(route.startsWith('/presupuesto/partidas/'))return budgetEditor(route.split('/').at(-1));
 if(route==='/movimientos'||route==='/movimientos/detalle')return movementList(false,route.endsWith('/detalle'));
 if(route==='/pendientes-categorizacion')return movementList(true);
 if(route.startsWith('/movimientos/'))return movementEditor(route.split('/').at(-1));
 if(route==='/patrimonio'||route==='/patrimonio/detalle')return wealth(route.endsWith('/detalle'));
 if(route==='/patrimonio/foto')return photoEditor();if(route==='/patrimonio/fichas')return catalogs(true);
 if(route.startsWith('/patrimonio/fichas/')&&route.endsWith('/periodos'))return liquidityEditor(route.split('/')[3]);
 if(route.startsWith('/patrimonio/fichas/'))return catalogEditor(route.split('/').at(-1),true);
 if(route==='/real')return annualReal();if(route==='/real/detalle')return title('Detalle del real anual',`Matriz de ${year} completo · ramas y Sin clasificar`,btn('Añadir movimiento','/movimientos/nuevo')+btn(expanded?'Contraer ramas':'Desplegar ramas','action:expand'))+categoryTable(visibleCats(),'real');
 if(route==='/indicadores'||route==='/indicadores/detalle')return indicators(route.endsWith('/detalle'));
 if(route==='/analisis'||route==='/mas')return analysis(route==='/mas');if(route==='/gestion')return management();
 if(route==='/categorias')return catalogs();if(route.startsWith('/categorias/'))return catalogEditor(route.split('/').at(-1));
 if(route==='/importaciones/csv'||route==='/importaciones/openbank')return importPage();if(route==='/importaciones/revision')return importReview();if(route==='/importaciones/resultado')return importResult();if(route.startsWith('/importaciones'))return importHistory(route.split('/')[3]);
 if(route==='/drive')return drive();if(route.startsWith('/copias-locales'))return copies(route.split('/')[2]);if(route==='/diagnostico')return diagnose();
 return title('No se puede abrir este destino','El enlace no es válido; no se consulta ni modifica la base.')+btn('Volver al origen','action:back');
}
function render(){
 const mobile=innerWidth<840,main=parentMain(route);$('#nav').innerHTML=[['inicio','Inicio'],['presupuesto','Presupuesto'],['movimientos','Movimientos'],['patrimonio','Patrimonio'],[mobile?'mas':'analisis',mobile?'Más':'Análisis']].map(([id,label])=>`<button data-route="/${id}" ${main==='/'+id||(id==='mas'&&main==='/analisis')?'aria-current="page"':''}>${icon(id)}<span>${label}</span></button>`).join('');
 $('#month').innerHTML=months.map((m,i)=>`<option value="${i}" ${i===month?'selected':''}>${m}</option>`).join('');$('#year').value=year;
 $('#breadcrumb').innerHTML=stack.length?`<button class="link" data-action="back">← Volver a ${routeNames[stack.at(-1).route]||'origen'}</button>`:!['/inicio','/presupuesto','/movimientos','/patrimonio','/analisis','/mas','/gestion','/copias-locales'].includes(route)?'<button class="link" data-action="back">← Volver al origen</button>':'';
 $('#content').innerHTML=query==='data'||route.startsWith('/copias-locales')?routeContent():query==='loading'?title(routeNames[route]||'Consulta',period())+'<div class="empty" role="status"><h2>Cargando datos</h2><div class="loadingline"></div><p>No se presentan importes ni pendientes como cero mientras carga.</p>'+btn('Completar carga de muestra','action:retry')+'</div>':query==='error'?title(routeNames[route]||'Consulta',period())+alert('<h2>No se pudieron leer los datos</h2><p>Conserva el periodo y vuelve a intentar. Las cifras no se sustituyen por ceros.</p>','error')+btn('Reintentar','action:retry',true):title(routeNames[route]||'Consulta',period())+`<div class="empty"><h2>No hay datos para esta consulta</h2><p>Sin registros cargados en la muestra de este estado. Una ausencia de foto o presupuesto tiene su propio motivo.</p><div class="actions">${btn('Registrar movimiento','/movimientos/nuevo')}${btn('Restablecer datos de referencia','action:retry')}</div></div>`;
 bind();if(route==='/importaciones/openbank'&&$('#importSample'))$('#importSample').value='xls';
 document.documentElement.style.setProperty('--nav-height',$('#nav').getBoundingClientRect().height+'px');
}
function sourceOpen(b){if(dirty){modal('Hay cambios sin guardar','<p>Resuelve el borrador antes de abrir otro ámbito.</p>',[['Seguir editando',()=>{}],['Descartar cambios',()=>{discardDraft();sourceOpen(b);},true]]);return;}const source=b.dataset.source,annual=b.dataset.annual==='true',cat=b.dataset.cat||'';const origin=snapshot();if(b.dataset.month!=null&&!annual)month=Number(b.dataset.month);filter={category:cat,scope:b.dataset.scope||'branch',search:'',account:'',range:annual?'year':'month'};origin.sourceFilter=structuredClone(filter);origin.sourceMonth=month;origin.sourceYear=year;origin.sourceValue=b.textContent;stack.push(origin);route=source==='budget'?'/presupuesto/partidas':'/movimientos/detalle';history.replaceState(null,'','#'+route);render();window.scrollTo(0,0);}
function bind(){
 $$('[data-batch-records]').forEach(b=>b.onclick=()=>{go('/movimientos/detalle');filter={category:'',scope:'branch',search:'',account:'',range:'year',batch:b.dataset.batchRecords};render();});
 $$('[data-income-month]').forEach(b=>b.onclick=()=>{stack.push(snapshot());month=Number(b.dataset.incomeMonth);route='/presupuesto/mensual';render();});
 $$('[data-expand-root]').forEach(b=>b.onclick=()=>{const root=b.dataset.expandRoot;expanded=false;branchExpanded.has(root)?branchExpanded.delete(root):branchExpanded.add(root);render();});
 $$('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$$('[data-source]').forEach(b=>b.onclick=()=>sourceOpen(b));
 $$('[data-select]').forEach(b=>b.onchange=()=>{b.checked?selected.add(b.dataset.select):selected.delete(b.dataset.select);});if($('#selectAll'))$('#selectAll').onchange=e=>{movementRows(true).forEach(r=>e.target.checked?selected.add(r.id):selected.delete(r.id));render();};
 $$('[data-categorize]').forEach(b=>b.onclick=()=>openCategorization([b.dataset.categorize]));$$('[data-edit-proposal]').forEach(b=>b.onclick=()=>editProposal(b.dataset.editProposal));
 $$('[data-delete-movement],[data-delete-budget]').forEach(b=>b.onclick=()=>{const id=b.dataset.deleteMovement||b.dataset.deleteBudget;modal('Eliminar registro','<p>Se eliminará solo este registro. No modifica fotos ni crea contrapartidas. Cancelar conserva los datos.</p>',[['Cancelar',()=>{}],['Eliminar registro',()=>{if($('#fault').value){notify('No se eliminó ningún registro.','error');return;}db.records=db.records.filter(r=>r.id!==id);db.localChanged=true;db.revision++;dirty=false;back();notify('Registro eliminado de la muestra.');},true]]);});
 $$('[data-archive]').forEach(b=>b.onclick=()=>{const c=db.cats.find(c=>c.id===b.dataset.archive);modal(c.active?'Archivar rama':'Reactivar rama','<p>Se conservan los registros históricos y sus importes. El archivo impide nuevas asignaciones.</p>',[['Cancelar',()=>{}],['Confirmar',()=>{const parent=c.path.split(' / ').slice(0,-1).join(' / ');if(!c.active&&parent&&!db.cats.find(p=>p.path===parent)?.active){notify('El padre está archivado. Reactiva primero la rama padre.','error');return;}const active=!c.active;db.cats.filter(p=>inBranch(p.path,c.path)).forEach(p=>p.active=active);db.localChanged=true;db.revision++;dirty=false;back();notify(active?'Rama reactivada.':'Rama archivada; histórico conservado.');},true]]);});
 $$('[data-restore]').forEach(b=>b.onclick=()=>restore(b.dataset.restore));$$('[data-photo-month]').forEach(b=>b.onclick=()=>{stack.push(snapshot());month=Number(b.dataset.photoMonth);route='/patrimonio';render();});
 $$('[data-finding]').forEach(b=>b.onclick=()=>{const r=diagnostic.items[Number(b.dataset.finding)];modal(r.title,`<p>${r.text}</p><p>Destino: ${routeNames[r.path]||r.path} · ${period()}</p>`,[['Cerrar',()=>{}],['Abrir origen',()=>go(r.path),true]]);});
 if($('#severity'))$('#severity').onchange=e=>$$('.finding').forEach(b=>b.hidden=!!e.target.value&&b.dataset.severity!==e.target.value);
 $$('form').forEach(f=>{f.oninput=()=>{dirty=true;};f.onchange=()=>{dirty=true;};f.onsubmit=e=>{e.preventDefault();if(f.id==='catalogForm'&&f.dataset.accounts==='true')saveAccountCatalog(f);else({movementForm:saveMovement,budgetForm:saveBudget,photoForm:savePhoto,catalogForm:saveCatalog,liquidityForm:saveLiquidity})[f.id]?.(f);};});
}
function action(name){
 if(name==='matrix'){$('.matrix-slot').classList.toggle('matrix-visible');return;}if(name==='back')return back();if(name==='expand'){expanded=!expanded;render();return;}
 if(name==='retry'){query='data';$('#queryState').value=query;render();return;}
 if(name==='filter'){filter.search=$('#search')?.value||'';filter.account=$('#accountFilter')?.value||'';filter.category=$('#categoryFilter')?.value||'';filter.scope=$('#scope')?.value||'branch';selected.clear();render();notify('Filtros aplicados · el contador y subtotal corresponden a todos los resultados del ámbito visible.');return;}
 if(name==='clearFilter'){filter={category:'',scope:'branch',search:'',account:'',range:'month'};selected.clear();render();return;}
 if(name==='originFilter'){const s=[...stack].reverse().find(s=>s.sourceFilter);if(s){filter=structuredClone(s.sourceFilter);month=s.sourceMonth;year=s.sourceYear;}render();return;}
 if(name==='range'){filter.range=filter.range==='year'?'month':'year';render();return;}
 if(name==='batch')return openCategorization([...selected]);
 if(name==='reviewImport'){importChoice=$('#importSample').value;go('/importaciones/revision');dirty=!['valid','errors'].includes(importChoice);return;}
 if(name==='cancelReview'){dirty=false;back();return;}
 if(name==='confirmImport')return confirmImport();if(name==='repeatImport'){go('/importaciones/revision');return;}
 if(name==='batchRecords'){filter.range='year';filter.category='';filter.search=importChoice==='overlap'?'Café':'';go('/movimientos/detalle');return;}
 if(name==='confirmProposal'){const target=Number(proposal[0].date.slice(0,4)),existing=db.records.filter(r=>r.type==='PRESUPUESTO'&&r.date.startsWith(String(target))).length;modal('Confirmar presupuesto de '+target,`<p>${proposal.length} partidas revisadas. ${existing?`Se sustituirán ${existing} partidas existentes del año destino.`:'No hay partidas existentes en el año destino.'}</p><p>El presupuesto y real de ${year} no se modifican. Cancelar conserva el borrador.</p>`,[['Seguir revisando',()=>{}],['Sustituir año destino',()=>{if($('#fault').value){notify('No se sustituyó el presupuesto. Se conserva íntegro el año destino anterior.','error');return;}db.records=db.records.filter(r=>!(r.type==='PRESUPUESTO'&&r.date.startsWith(String(target))));db.records.push(...proposal.map(r=>({...r,type:'PRESUPUESTO',concept:'Propuesta',account:'',discretion:''})));db.localChanged=true;db.revision++;dirty=false;go('/presupuesto',false);notify('Presupuesto de '+target+' guardado. Cambia el año explícitamente para consultarlo.');},true]]);return;}
 if(name==='upload')return upload();if(name==='download')return download();if(name==='diagnose')return runDiagnostic();
}
function changePeriod(m,y){const apply=()=>{month=m;year=y;selected.clear();if(filter.range==='month')filter.range='month';if(diagnostic&&diagnostic.period!==key())diagnostic.case='stale';render();};if(dirty){modal('Cambiar periodo con un borrador','<p>El cambio de periodo requiere resolver los cambios sin guardar.</p>',[['Seguir editando',()=>render()],['Descartar y cambiar',()=>{discardDraft();apply();},true]]);}else apply();}
$('#month').onchange=e=>changePeriod(Number(e.target.value),year);$('#year').onchange=e=>changePeriod(month,Number(e.target.value));
$('#scenario').onchange=e=>reset(e.target.value);$('#queryState').onchange=e=>{query=e.target.value;render();};$('#reset').onclick=()=>reset();$('#scale').onclick=()=>{document.documentElement.classList.toggle('bigtext');$('#scale').textContent=document.documentElement.classList.contains('bigtext')?'Texto 100 %':'Texto 200 %';render();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').open&&stack.length){e.preventDefault();back();}if(e.altKey&&e.key==='ArrowLeft'){e.preventDefault();if($('#modal').open)closeModal();else back();}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});window.addEventListener('resize',()=>{const targetMobile=innerWidth<840;if($('#nav').textContent.includes('Más')!==targetMobile)render();document.documentElement.style.setProperty('--nav-height',$('#nav').getBoundingClientRect().height+'px');});
window.addEventListener('hashchange',()=>{const next=decodeURIComponent(location.hash.slice(1));if(next!==route)go(next,false);});
const initialRoute=decodeURIComponent(location.hash.slice(1));reset();if(initialRoute&&initialRoute!=='/inicio')go(initialRoute,false);
